import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.Cyu1VozZ.js";const g=JSON.parse('{"title":"External Datasources","description":"","frontmatter":{},"headers":[],"relativePath":"sheets/datasources.md","filePath":"sheets/datasources.md"}'),r={name:"sheets/datasources.md"};function n(l,e,i,c,h,d){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="external-datasources" tabindex="-1">External Datasources <a class="header-anchor" href="#external-datasources" aria-label="Permalink to &quot;External Datasources&quot;">​</a></h1><p>A <strong>datasource</strong> connects a spreadsheet to external data. You write a SQL query and its results appear in a read-only tab, right next to your regular editable sheets.</p><p>There are two kinds of connection: a <strong>PostgreSQL</strong> database, and a <strong>Lakehouse</strong> table held in object storage. Most of this page describes PostgreSQL; see <a href="#lakehouse-tables">Lakehouse tables</a> for the other.</p><h2 id="connect-a-database" tabindex="-1">Connect a database <a class="header-anchor" href="#connect-a-database" aria-label="Permalink to &quot;Connect a database&quot;">​</a></h2><ol><li>Click the <strong>+</strong> at the end of the tab bar. The menu offers <strong>New Sheet</strong>, <strong>New DataSource</strong>, and <strong>New Lakehouse</strong> — choose <strong>New DataSource</strong>.</li><li>The <strong>Select DataSource</strong> dialog lists the connections your workspace already has. Pick one to reuse it, or create a new connection and fill in its details: <ul><li><strong>Name</strong> — a label for the connection</li><li><strong>Host</strong> and <strong>Port</strong> (defaults to <code>5432</code>)</li><li><strong>Database</strong>, <strong>Username</strong>, and <strong>Password</strong></li><li><strong>SSL</strong> — toggle on if your database requires it</li></ul></li><li>Click <strong>Test Connection</strong> to confirm the credentials work, then save.</li></ol><p>A new tab is added with a database icon to distinguish it from sheet tabs.</p><h2 id="run-a-query" tabindex="-1">Run a query <a class="header-anchor" href="#run-a-query" aria-label="Permalink to &quot;Run a query&quot;">​</a></h2><p>The datasource tab has a SQL editor at the top and a results grid below it.</p><ol><li>Type a <code>SELECT</code> query — for example, <code>SELECT * FROM users LIMIT 100</code>.</li><li>Click <strong>Execute</strong>, or press <strong>⌘+Enter</strong> / <strong>Ctrl+Enter</strong>.</li></ol><p>The results load into the grid below: the first row holds the column names and each following row is a record. Re-run the query with <strong>Execute</strong> whenever you want fresh data — results don&#39;t refresh automatically.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Queries are capped at 10,000 rows and a 30-second runtime, so add a <code>LIMIT</code> clause when exploring large tables.</p></div><h2 id="working-with-results" tabindex="-1">Working with results <a class="header-anchor" href="#working-with-results" aria-label="Permalink to &quot;Working with results&quot;">​</a></h2><ul><li>The results grid is <strong>read-only</strong> — it reflects the database, so you can&#39;t edit, sort, or filter the cells in place. Shape the data with SQL instead.</li><li>A datasource tab <strong>can&#39;t be referenced from a formula</strong> in another tab. Cross-sheet references resolve only against regular sheet tabs, so <code>DataSource1!A1</code> comes back empty rather than reporting an error. To build a summary on top of a query, shape it in SQL, or copy the results (<strong>⌘/Ctrl+C</strong> works in the read-only grid) and paste them into a sheet tab.</li></ul><h2 id="lakehouse-tables" tabindex="-1">Lakehouse tables <a class="header-anchor" href="#lakehouse-tables" aria-label="Permalink to &quot;Lakehouse tables&quot;">​</a></h2><p>The third entry in the <strong>+</strong> menu, <strong>New Lakehouse</strong>, reads a table sitting in object storage instead of connecting to a database server. Choose the <strong>table format</strong> — <strong>Apache Iceberg</strong> or <strong>Delta Lake</strong> — and the <strong>storage</strong> that holds it: Amazon S3, an S3-compatible service, Google Cloud Storage, Azure Blob / ADLS, or a local filesystem path the server has been configured to allow.</p><p>Lakehouse sources are shared with the workspace on exactly the same terms as database connections, so the section below applies to them too.</p><h2 id="connections-are-shared-with-the-workspace" tabindex="-1">Connections are shared with the workspace <a class="header-anchor" href="#connections-are-shared-with-the-workspace" aria-label="Permalink to &quot;Connections are shared with the workspace&quot;">​</a></h2><p>A saved connection belongs to the <strong>workspace</strong>, not to the person who created it. Every member of the workspace can:</p><ul><li>choose the connection when creating a datasource tab,</li><li>run queries through it — whoever presses <strong>Execute</strong>, the query runs against the username and password stored with the connection,</li><li>change its connection details, or delete it.</li></ul><p>Query <strong>results</strong>, by contrast, are never shared. Only the SQL text is saved into the document, so a collaborator who opens a datasource tab sees the saved query and an empty grid until they run it themselves.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Point a datasource at a <strong>least-privilege, read-only database account</strong>. Everyone in the workspace shares the credentials you save, so the account should be able to reach only the data you are willing to show all of them.</p><p>Wafflebase accepts a single <code>SELECT</code> (or <code>WITH</code>) statement and rejects statements such as <code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>, and <code>DROP</code>. That check runs in Wafflebase, though — a read-only database account is what actually guarantees a query cannot change your data.</p></div><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li>Database connections are <strong>PostgreSQL</strong>; Lakehouse sources read Apache Iceberg and Delta Lake tables.</li><li>Only the latest query for a tab is saved.</li></ul>',23)])])}const p=t(r,[["render",n]]);export{g as __pageData,p as default};
